process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='';
const DEP=Buffer.from('','base64').toString();
async function jsonSafe(r){ const t=await r.text();
  const a=t.indexOf('['), o=t.indexOf('{');
  const i=(a>=0&&(a<o||o<0))?a:o; if(i<0) return null;
  try{ return JSON.parse(t.slice(i)); }catch(e){ return null; } }
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'s8', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'s8');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await jsonSafe(r)||{};
}
async function off(id){ if(!id) return; await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'S8'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await jsonSafe(r);
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP s8 set', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP s8 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_s8=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.deploy=await jsonSafe(resp);

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.setDefaultTimeout(15000);
  try{ await page.goto(`${WP}/?ps_l4=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:45000}); }catch(e){}
  await pause(3500);
  out.rail=await page.evaluate(()=>Array.prototype.map.call(
    document.querySelectorAll('.pskat-rail a'), a=>a.textContent.replace(/\s+/g,' ').trim())
    .filter(x=>/savikain|skolos|Visos/i.test(x)));
  out.suvestine=await page.evaluate(()=>{
    const p=document.querySelectorAll('.pskat-suv .p');
    return Array.prototype.map.call(p,x=>x.innerText.replace(/\n+/g,': ').trim());
  });
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/s8_savikaina.png', png.toString('base64'),'s8');
  out.js_klaidos=jsErr.slice(0,6);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await jsonSafe(r);
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/s8.json', out);
}
main().catch(async e=>{ await putJson('analize/s8.json',{klaida:String(e).slice(0,400)}); });
